pub fn absolute_difference(expected: i64, actual: i64) -> i64 {
    (expected - actual).abs()
}

rust.main.rs:
mod ledger;

use ledger::absolute_difference;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let count: usize = lines.next().unwrap().parse().unwrap();
    for _ in 0..count {
        let mut parts = lines.next().unwrap().split('|');
        let expected: i64 = parts.next().unwrap().parse().unwrap();
        let actual: i64 = parts.next().unwrap().parse().unwrap();
        println!("difference={}", absolute_difference(expected, actual));
    }
}

