pub fn format_message(index: usize, message: &str) -> String {
    format!("{index}|{message}")
}

rust.main.rs:
mod digest_rules;

use digest_rules::format_message;
use std::fs;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.split_terminator('\n');
    let title = lines.next().unwrap_or("");
    let count: usize = lines.next().unwrap_or("0").parse().unwrap();
    let messages: Vec<&str> = (0..count).map(|_| lines.next().unwrap_or("")).collect();
    let mut contents = format!("{title}\n");
    for (offset, message) in messages.iter().enumerate() {
        contents.push_str(&format_message(offset + 1, message));
        contents.push('\n');
    }
    std::fs::write("priority_digest.txt", contents).unwrap();
    let characters: usize = messages.iter().map(|message| message.chars().count()).sum();
    println!("saved={}|characters={characters}", messages.len());
}
